<?php
namespace App\Http\Controllers;use App\Models\AlerteMeteo;use App\Services\OpenMeteoService;use App\Services\WeatherAlertService;use Illuminate\Http\Request;
class MeteoController extends Controller{public function index(Request $r,OpenMeteoService $meteo,WeatherAlertService $levels){$quartier=$r->user()->quartier;if(!$quartier)return view('meteo.index',['quartier'=>null,'alertesActives'=>collect()]);$alertesActives=AlerteMeteo::where('quartier_id',$quartier->id)->where('actif',true)->where(fn($q)=>$q->whereNull('date_debut')->orWhere('date_debut','<=',now()))->where(fn($q)=>$q->whereNull('date_fin')->orWhere('date_fin','>=',now()))->latest()->get();try{$weather=$meteo->weather($quartier);$niveau=$levels->niveau($weather['temperature']);return view('meteo.index',compact('quartier','weather','niveau','alertesActives'));}catch(\RuntimeException $e){return view('meteo.index',compact('quartier','alertesActives'))->withErrors(['meteo'=>$e->getMessage()]);}}}
